use File::Find;
use File::Basename;

my $root = "/bench/repo";
my @decls;  # {symbol, name, recv, path}
my %decl_set;
my %name_to_keys;

sub read_file {
    my ($p) = @_;
    open my $fh, '<', $p or return '';
    local $/; my $c = <$fh>; close $fh; return $c;
}

find(sub {
    return unless /\.go$/ && $_ !~ /_test\.go$/;
    my $full = $File::Find::name;
    return unless index($full, "$root/internal/") == 0;
    my $rel = substr($full, length($root)+1);
    my $content = read_file($full);
    while ($content =~ /^func (?:\([^)]+\)\s+)?(?:\*?(\w+)\s+)?(\w+)\(/mg) {
        my ($recv, $name) = ($1, $2);
        next if $name eq 'init';
        my $symbol = $recv ? "($recv).$name" : $name;
        my $key = "$symbol\x00$rel";
        $decl_set{$key} = 1;
        push @{$name_to_keys{$name}}, $key;
        push @decls, {symbol=>$symbol, name=>$name, recv=>$recv, path=>$rel};
    }
}, "$root/internal");

my %fan_sites;
my %fan_files;

find(sub {
    return unless /\.go$/ && $_ !~ /_test\.go$/;
    my $full = $File::Find::name;
    return if index($full, '/proto/gen/') >= 0 || index($full, '/web/') >= 0;
    my $rel = substr($full, length($root)+1);
    my $content = read_file($full);
    my @lines = split /\n/, $content;
