        next if $line =~ /\bfunc\b/;
        while ($line =~ /(?:\.|\b)(\w+)\s*\(/g) {
            my $name = $1;
            next unless exists $name_to_keys{$name};
            for my $key (@{$name_to_keys{$name}}) {
                next unless exists $decl_set{$key};
                $fan_sites{$key}++;
                $fan_files{$key}{$rel} = 1;
            }
        }
    }
}, $root);

my @ranked = sort { ($fan_sites{$b}//0) <=> ($fan_sites{$a}//0) || scalar(keys %{$fan_files{$b}//{}}) <=> scalar(keys %{$fan_files{$a}//{}}) } keys %decl_set;

print "TOP 25:\n";
