    return 0;
}

my @entities = qw(Attachment User Memo MemoRelation MemoShare Reaction Inbox IdentityProvider UserIdentity UserSetting InstanceSetting);

my @files;
open my $fl,'-|',"find $root -name '*.go' ! -name '*_test.go' ! -path '*/proto/gen/*' ! -path '*/web/*'" or die $!;
while(<$fl>){ chomp; push @files, substr($_, length($root)+1); }
close $fl;

my %counts;
for my $rel (@files) {
    next if is_data_layer($rel);
    my $content = read_file("$root/$rel");
    my $pkgpath = $rel; $pkgpath =~ s/\/[^\/]+$//; $pkgpath='.' if $pkgpath eq $rel;
    for my $type (@entities) {
        if ($content =~ /\bstore\.$type\b/) {
            $counts{$type}{$pkgpath} = 1;
        }
    }
}

my @ranked = sort { scalar(keys %{$counts{$b}}) <=> scalar(keys %{$counts{$a}}) || $a cmp $b } @entities;
for my $type (@ranked) {
    my @pkgs = sort keys %{$counts{$type}};
    print scalar(@pkgs), "\t$type\n";
    print "  @pkgs\n\n";
}
